function parse([q, line]: [string, string]): SurveyQuestion {
  const answers = line.split('|').map((part) => {
    const [names, pts] = part.split('=');
    const all = names.split('،').map((n) => n.trim()).filter(Boolean);
    return { text: all[0], points: Number(pts.trim()), aliases: [...new Set(all.slice(1))].filter((a) => a !== all[0]) };
  });
  return { q, answers };
}

export const SURVEY_QUESTIONS: SurveyQuestion[] = RAW.map(parse);
